css:
.erp-sim-container {
    padding: 28px;
    background: #0f1724;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #cbd5e1;
}
.erp-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #0f1d35 100%);
    border-left: 6px solid #f59e0b;
    border-radius: 6px;
    padding: 26px 32px;
    margin-bottom: 24px;
}
.erp-sim-header h1 {
    color: #f1f5f9;
    font-size: 1.6rem;
    margin: 10px 0 6px;
    font-weight: 700;
    letter-spacing: 0.01em;
}
.erp-sim-header p {
    color: #94a3b8;
    margin: 0;
    font-size: 0.95rem;
}
.erp-sim-header-meta {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}
.erp-sim-tag {
    display: inline-block;
    background: rgba(245,158,11,0.15);
    color: #fbbf24;
    border: 1px solid rgba(245,158,11,0.4);
    padding: 4px 10px;
    border-radius: 12px;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.erp-sim-tag-alt {
    background: rgba(96,165,250,0.12);
    color: #93c5fd;
    border-color: rgba(96,165,250,0.4);
}
.erp-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    padding: 12px 18px;
    background: #1e293b;
    border-radius: 4px;
    border: 1px solid #334155;
}
.erp-sim-period-counter {
    color: #cbd5e1;
    font-size: 0.9rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.erp-sim-period-counter span:nth-child(2),
.erp-sim-period-counter span:nth-child(4) {
    color: #fbbf24;
    font-size: 1.25rem;
    font-weight: 700;
    margin: 0 4px;
}
.erp-sim-round-tag {
    color: #93c5fd;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    padding: 4px 12px;
    background: rgba(96,165,250,0.1);
    border-radius: 4px;
}
.erp-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.erp-sim-kpi-card {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 18px 16px;
    position: relative;
    overflow: hidden;
}
.erp-sim-kpi-card::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #60a5fa, #34d399);
}
.erp-sim-kpi-primary::after {
    background: linear-gradient(90deg, #f59e0b, #fbbf24);
}
.erp-sim-kpi-label {
    color: #94a3b8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 10px;
    font-weight: 600;
}
.erp-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #f1f5f9;
    line-height: 1;
    display: inline-block;
}
.erp-sim-kpi-primary .erp-sim-kpi-value {
    color: #fbbf24;
    font-size: 2.4rem;
}
.erp-sim-kpi-unit {
    display: inline-block;
    color: #7386a0;
    font-size: 0.85rem;
    margin-left: 6px;
    font-weight: 500;
}
.erp-sim-modules {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 18px;
    margin-bottom: 22px;
}
.erp-sim-modules-label {
    color: #94a3b8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 14px;
    font-weight: 600;
}
.erp-sim-modules-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
    gap: 10px;
}
.erp-sim-module {
    background: #0f1724;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 14px 8px;
    text-align: center;
    transition: all 0.25s ease;
}
.erp-sim-module span {
    display: block;
    font-size: 1.1rem;
    font-weight: 700;
    color: #6f84a0;
    margin-bottom: 6px;
    letter-spacing: 0.05em;
}
.erp-sim-module small {
    display: block;
    font-size: 0.65rem;
    color: #6f84a0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 600;
}
.erp-sim-module.is-active {
    background: rgba(52,211,153,0.1);
    border-color: #34d399;
    box-shadow: 0 0 14px rgba(52,211,153,0.25);
}
.erp-sim-module.is-active span,
.erp-sim-module.is-active small {
    color: #6ee7b7;
}
.erp-sim-briefing {
    background: #1e293b;
    border: 1px solid #334155;
    border-left: 4px solid #60a5fa;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.erp-sim-briefing-label {
    color: #93c5fd;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 700;
}
.erp-sim-briefing h3 {
    color: #f1f5f9;
    font-size: 1.18rem;
    margin: 0 0 12px;
    font-weight: 700;
}
.erp-sim-briefing p {
    color: #cbd5e1;
    font-size: 0.95rem;
    line-height: 1.6;
    margin: 0;
}
.erp-sim-controls {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.erp-sim-controls h3 {
    color: #f1f5f9;
    font-size: 0.95rem;
    margin: 0 0 16px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
}
.erp-sim-controls label {
    display: block;
    color: #94a3b8;
    font-size: 0.75rem;
    margin-bottom: 8px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.erp-sim-controls select,
.erp-sim-controls input[type="number"],
.erp-sim-controls input[type="text"] {
    background: #0f1724;
    border: 1px solid #475569;
    color: #f1f5f9;
    border-radius: 4px;
    padding: 11px 14px;
    width: 100%;
    font-size: 0.92rem;
    margin-bottom: 16px;
}
.erp-sim-controls select option {
    background: #1e293b;
    color: #f1f5f9;
}
.erp-sim-controls select:focus,
.erp-sim-controls input:focus {
    outline: none;
    border-color: #f59e0b;
    box-shadow: 0 0 0 3px rgba(245,158,11,0.15);
}
.erp-sim-action-row {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}
.erp-sim-controls .btn-primary {
    background: #f59e0b;
    border-color: #f59e0b;
    color: #1a2744;
    font-weight: 700;
    padding: 11px 26px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.82rem;
    border-radius: 4px;
    transition: all 0.2s ease;
}
.erp-sim-controls .btn-primary:hover {
    background: #fbbf24;
    border-color: #fbbf24;
    transform: translateY(-1px);
}
.erp-sim-controls .btn-outline-light {
    border: 1px solid #475569;
    color: #cbd5e1;
    background: transparent;
    padding: 8px 16px;
    font-size: 0.78rem;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.erp-sim-controls .btn-outline-light:hover {
    background: #334155;
    color: #f1f5f9;
}
.erp-sim-insight {
    background: rgba(52,211,153,0.08);
    border: 1px solid rgba(52,211,153,0.3);
    border-left: 4px solid #34d399;
    border-radius: 6px;
    padding: 18px 24px;
    margin-bottom: 22px;
}
.erp-sim-insight-label {
    color: #6ee7b7;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 700;
}
.erp-sim-insight p {
    color: #d1fae5;
    margin: 0;
    line-height: 1.6;
    font-size: 0.93rem;
}
.erp-sim-history {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 18px 22px;
    margin-bottom: 22px;
    overflow-x: auto;
}
.erp-sim-history h3 {
    color: #f1f5f9;
    font-size: 0.95rem;
    margin: 0 0 14px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
}
.erp-sim-history table {
    color: #cbd5e1;
    font-size: 0.85rem;
    width: 100%;
    margin: 0;
    border-collapse: collapse;
}
.erp-sim-history table thead th {
    background: #0f1724;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.7rem;
    font-weight: 700;
    border: 1px solid #334155;
    padding: 10px 12px;
    text-align: left;
}
.erp-sim-history table td {
    border: 1px solid #334155;
    padding: 9px 12px;
    color: #cbd5e1;
}
.erp-sim-history table tbody tr:nth-child(odd) {
    background: rgba(255,255,255,0.02);
}
.erp-sim-chart-row {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 18px;
    margin-bottom: 24px;
}
.erp-sim-chart-card {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 6px;
    padding: 18px;
    height: 320px;
    display: flex;
    flex-direction: column;
}
.erp-sim-chart-card h4 {
    color: #94a3b8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 14px;
    font-weight: 700;
}
.erp-sim-chart-card canvas {
    flex: 1;
    max-height: 260px;
}
@media (max-width: 768px) {
    .erp-sim-container {
        padding: 16px;
    }
    .erp-sim-chart-row {
        grid-template-columns: 1fr;
    }
    .erp-sim-period-bar {
        flex-direction: column;
        align-items: flex-start;
        gap: 8px;
    }
    .erp-sim-action-row {
        flex-direction: column;
        align-items: stretch;
    }
    .erp-sim-controls .btn-primary,
    .erp-sim-controls .btn-outline-light {
        width: 100%;
    }
    .erp-sim-kpi-primary .erp-sim-kpi-value {
        font-size: 2rem;
    }
}

/* a11y: visible keyboard focus on every interactive control */
.erp-sim-container select:focus-visible,
.erp-sim-container input:focus-visible,
.erp-sim-container button:focus-visible {
    outline: 3px solid #38bdf8;
    outline-offset: 2px;
}

.erp-sim-complete {
    margin: 18px 0 24px 0;
    padding: 20px 22px;
    border: 1px solid #1e3a5f;
    border-radius: 10px;
    background: #101f33;
    color: #e2e8f0;
}
.erp-sim-complete h3 { margin: 0 0 6px 0; color: #38bdf8; }
.erp-sim-complete-band { margin: 0 0 10px 0; font-weight: 600; color: #93c5fd; }
.erp-sim-complete-kpis { margin: 0 0 12px 18px; padding: 0; }
.erp-sim-complete-kpis li { margin: 2px 0; }

@media (prefers-reduced-motion: reduce) {
    .erp-sim-container *,
    .erp-sim-container *::before,
    .erp-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

