        }
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    erpMaturity: 25,
                    masterDataQuality: 50,
                    processIntegration: 20,
                    auditCompliance: 30,
                    changeMgmtInvestment: 0,
                    maturityHistory: [],
                    masterDataHistory: [],
                    integrationHistory: [],
                    auditHistory: [],
                    changeMgmtHistory: [],
                    activeModules: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { choice: '' };
            }
            this._renderedStep = null;
            this._refreshScenario(state);
            this._syncControlsFromDecisions(state);
            if (!this._langBound) {
                this._langBound = true;
                const self = this;
                document.addEventListener('express:langchanged', function() {
                    const live = window.mySimulation && window.mySimulation.state;
                    if (!live) return;
                    self._renderedStep = null;
                    self._refreshScenario(live);
                });
            }
        }

        _syncControlsFromDecisions(state) {
            const dec = (state && state.decisions) || {};
            const sel = document.getElementById('decisionInput');
            if (sel && dec.choice) sel.value = String(dec.choice);
        }

        _lang() {
            // window.mySimulation.language is the framework property. .currentLanguage
            // does not exist and reads undefined, silently falling back to English.
            const l = (window.mySimulation && window.mySimulation.language) || 'en';
            return String(l).split('-')[0].toLowerCase();
        }

        _t(key, fallback) {
            try {
                const v = window.mySimulation.t(key);
                if (v && v !== key) return v;
            } catch (e) {}
            return fallback;
        }

        // A round with its texts in the current language: ROUNDS keeps keys and deltas only.
        _round(idx) {
            const r = this.ROUNDS[idx];
            const self = this;
            return {
                round: r.round,
                roundLabel: this._t(r.roundKey, ''),
                title: this._t(r.key + '_title', ''),
                scenario: this._t(r.key + '_text', ''),
                modules: r.modules,
                options: r.options.map(function(o) {
                    return {
                        value: o.value,
                        deltas: o.deltas,
                        label: self._t(r.key + '_' + o.value, o.value),
                        feedback: self._t(r.key + '_' + o.value + '_fb', '')
                    };
                })
            };
        }

        // History cell in the current language, from the period the row records.
        _stepText(entry, field, fallback) {
            const p = entry && (entry.period || (entry.results && entry.results.period));
            if (!p) return fallback;
            const r = this.ROUNDS[Math.min(p - 1, this.ROUNDS.length - 1)];
            return field === 'round' ? this._t(r.roundKey, fallback) : this._t(r.key + '_title', fallback);
        }

        _dimensionCeilings() {
            // Reachable ceiling per dimension, derived from the authored ROUNDS table:
            // the starting value plus the best available delta in each step, capped at
            // 100. Four dimensions saturate at 100 long before the last step and
            // changeMgmtInvestment tops out at 31, so a raw mean of the five is not a
            // usable score. Computed once and cached.
            if (this._ceilings) return this._ceilings;
            const start = { maturity: 25, masterData: 50, integration: 20, audit: 30, change: 0 };
            const keys = ['maturity', 'masterData', 'integration', 'audit', 'change'];
            const out = {};
            keys.forEach(function(k) { out[k] = start[k]; });
            this.ROUNDS.forEach(function(r) {
                keys.forEach(function(k) {
                    let best = -Infinity;
                    r.options.forEach(function(o) {
                        const d = (o.deltas && o.deltas[k]) || 0;
                        if (d > best) best = d;
                    });
                    if (best > 0) out[k] += best;
                });
            });
            keys.forEach(function(k) { out[k] = Math.max(1, Math.min(100, out[k])); });
            this._ceilings = out;
            return out;
        }

        _normalisedComposite(dims) {
            const c = this._dimensionCeilings();
            const keys = ['maturity', 'masterData', 'integration', 'audit', 'change'];
            let sum = 0;
            keys.forEach(function(k) {
                const raw = Math.max(0, dims[k] || 0);
                sum += Math.min(100, (raw / c[k]) * 100);
            });
            return Math.round(sum / keys.length);
        }


        validateDecisions(decisions) {
            const sel = document.getElementById('decisionInput');
            const value = sel ? sel.value : '';
            decisions.choice = value;

            if (!value) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('choice_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this._round(idx);
            const choice = state.decisions.choice;
            const option = round.options.find(o => o.value === choice) || round.options[0];

            const ds = state.domainState;
            ds.erpMaturity          = this._clamp(ds.erpMaturity          + option.deltas.maturity);
            ds.masterDataQuality    = this._clamp(ds.masterDataQuality    + option.deltas.masterData);
            ds.processIntegration   = this._clamp(ds.processIntegration   + option.deltas.integration);
            ds.auditCompliance      = this._clamp(ds.auditCompliance      + option.deltas.audit);
            ds.changeMgmtInvestment = this._clamp(ds.changeMgmtInvestment + option.deltas.change);

            ds.maturityHistory.push(ds.erpMaturity);
            ds.masterDataHistory.push(ds.masterDataQuality);
            ds.integrationHistory.push(ds.processIntegration);
            ds.auditHistory.push(ds.auditCompliance);
            ds.changeMgmtHistory.push(ds.changeMgmtInvestment);

            ds.activeModules = round.modules.slice();

            // Platform score: the 0-100 composite of getPerformanceSummary, each dimension over its reachable ceiling, on the current dimension values.
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, this._normalisedComposite({
                maturity: ds.erpMaturity, masterData: ds.masterDataQuality, integration: ds.processIntegration,
                audit: ds.auditCompliance, change: ds.changeMgmtInvestment
            }))) });

            this._showInsight(option.feedback);

            const self = this;
            setTimeout(((__eqilNext) => function() {
                const live = (window.mySimulation && window.mySimulation.state) || state;
                self._refreshScenario(Object.assign({}, live, {
                    currentPeriod: __eqilNext
                }));
            })((state.currentPeriod || 1) + 1), 450);

            return {
                period: state.currentPeriod,
                round: round.roundLabel,
                step: round.title,
                choice: option.label,
                modules: round.modules.join(', '),
                maturity: ds.erpMaturity,
                masterData: ds.masterDataQuality,
                integration: ds.processIntegration,
                audit: ds.auditCompliance,
                change: ds.changeMgmtInvestment
            };
        }

