        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const last = history[history.length - 1].results || {};
            const dims = {
                maturity: last.maturity || 0,
                masterData: last.masterData || 0,
                integration: last.integration || 0,
                audit: last.audit || 0,
                change: last.change || 0
            };
            const rawMean = Math.round(
                (dims.maturity + dims.masterData + dims.integration + dims.audit + dims.change) / 5);
            const composite = this._normalisedComposite(dims);

            let perf = 'beginner';
            if (composite > 55) perf = 'solid';
            if (composite > 70) perf = 'good';
            if (composite > 82) perf = 'excellent';

            const labels = {
                beginner: this._t('perf_beginner', 'Beginner'),
                solid: this._t('perf_solid', 'Solid'),
                good: this._t('perf_good', 'Good'),
                excellent: this._t('perf_excellent', 'Excellent')
            };

            const ceil = this._dimensionCeilings();
            const insights = [];
            if (dims.audit < ceil.audit * 0.5) {
                insights.push(this._t('ins_audit', 'Audit-compliance score is low - revisit segregation-of-duties, three-way-match, and credit-check decisions.'));
            }
            if (dims.masterData < ceil.masterData * 0.5) {
                insights.push(this._t('ins_master_data', 'Master-data quality is in the bottom half of its reachable range - the textbook research warns this is the most predictable failure cause.'));
            }
            if (dims.change < ceil.change * 0.5) {
                insights.push(this._t('ins_change', 'Change-management investment is under-funded; the field benchmark is 12-18% of programme cost.'));
            }
            if (dims.integration > ceil.integration * 0.7 && dims.audit > ceil.audit * 0.7) {
                insights.push(this._t('ins_strong', 'Integration and controls both strong - the implementation pattern is defensible to the steering committee.'));
            }
            if (!insights.length) {
                insights.push(this._t('ins_balanced', 'Balanced design across the five dimensions - defensible recommendation for the steering committee.'));
            }

            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                rawMean: rawMean,
                ceilings: ceil,
                maturity: dims.maturity,
                masterData: dims.masterData,
                integration: dims.integration,
                audit: dims.audit,
                change: dims.change,
                performance: perf,
                performanceKey: perf,
                performanceLabel: labels[perf],
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const c = s.ceilings || this._dimensionCeilings();
            const rows = [
                [this._t('dim_maturity', 'Maturity'), s.maturity, c.maturity],
                [this._t('dim_master_data', 'Master Data'), s.masterData, c.masterData],
                [this._t('dim_integration', 'Integration'), s.integration, c.integration],
                [this._t('dim_audit', 'Audit'), s.audit, c.audit],
                [this._t('dim_change', 'Change Mgmt'), s.change, c.change]
            ];
            const parts = [];
            parts.push('<div class="erp-sim-complete">');
            parts.push('<h3>' + this._t('done_title', 'Walkthrough complete') + '</h3>');
            parts.push('<p class="erp-sim-complete-band">' + (s.performanceLabel || '')
                + ' &middot; ' + (s.overallScore || 0) + '/100</p>');
            parts.push('<ul class="erp-sim-complete-kpis">');
            rows.forEach(function(r) {
                parts.push('<li>' + r[0] + ': ' + (r[1] || 0) + ' / ' + r[2] + '</li>');
            });
            parts.push('</ul>');
            (s.insights || []).forEach(function(i) { parts.push('<p>' + i + '</p>'); });
            parts.push('</div>');
            return parts.join('');
        }


