        // ===== Internal helpers =====

        _clamp(v) {
            return Math.max(0, Math.min(100, v));
        }
        _refreshScenario(state) {
            const total = this.ROUNDS.length;
            const period = (state && state.currentPeriod) || 1;
            const controls = document.getElementById('decisionControls');
            const done = document.getElementById('runCompletePanel');

            if (period > total) {
                // Terminal state. The previous version clamped the index and left the
                // select and Submit live on the last step forever.
                if (controls) controls.style.display = 'none';
                if (done) {
                    done.style.display = 'block';
                    done.innerHTML = '<h3>' + this._t('done_title', 'Walkthrough complete') + '</h3>'
                        + '<p>' + this._t('done_body', 'Every decision point is locked. Your ERP design is on the record.') + '</p>';
                }
                const tagDone = document.getElementById('roundTag');
                if (tagDone) tagDone.textContent = this._t('done_title', 'Walkthrough complete');
                this._hideInsight();
                return;
            }

            if (controls) controls.style.display = '';
            if (done) done.style.display = 'none';

            const idx = Math.min(period - 1, total - 1);
            const round = this._round(idx);
            const stepKey = idx + ':' + this._lang();

            const titleEl = document.getElementById('scenarioTitle');
            if (titleEl) titleEl.textContent = round.title;

            const textEl = document.getElementById('scenarioText');
            if (textEl) textEl.innerHTML = round.scenario;

            const tagEl = document.getElementById('roundTag');
            if (tagEl) tagEl.textContent = round.roundLabel;

            const sel = document.getElementById('decisionInput');
            if (sel && this._renderedStep !== stepKey) {
                // Rebuild only on a genuine step or language change, so a stray re-render
                // cannot wipe a selection the player has already made.
                sel.innerHTML = '';
                const placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = this._t('choice_placeholder', 'Select an option...');
                sel.appendChild(placeholder);
                round.options.forEach(function(opt) {
                    const o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = opt.label;
                    sel.appendChild(o);
                });
                sel.value = '';
                this._renderedStep = stepKey;
            }

            this._lightModules(round.modules);
            this._hideInsight();
        }


        _lightModules(modules) {
            const expand = (modules.indexOf('ALL') > -1) ? this.MODULES : modules;
            const self = this;
            this.MODULES.forEach(function(m) {
                const el = document.querySelector('[data-module="' + m + '"]');
                if (!el) return;
                if (expand.indexOf(m) > -1) el.classList.add('is-active');
                else el.classList.remove('is-active');
            });
        }

        _showInsight(text) {
            const panel = document.getElementById('insightPanel');
            const body = document.getElementById('insightText');
            if (panel && body) {
                body.innerHTML = text;
                panel.style.display = 'block';
            }
        }

        _hideInsight() {
            const panel = document.getElementById('insightPanel');
            if (panel) panel.style.display = 'none';
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new ERPArchitectureAdapter(), {
            simulationType: 'erp_architecture_walkthrough',
            maxPeriods: 15,
            autoSaveInterval: 30000
        });
    });

